# Settings shared by every dlrmv4 system configuration (config_MI350X_*.sh sources this file).
# Generated by the submission packaging tool from the launch parameters of the submitted runs.
# These files set the environment for run_with_docker.sh / run_with_docker_slurm.sh only. The
# training hyperparameters and feature switches not listed here come from the gin file
# generative_recommenders/dlrm_v4/train/gin/yambda_5b.gin, which is also the MLPerf
# config_filename logged by the trainer.

# DGXSYSTEM = this config's name without "config_" and ".sh" (AMD/NVIDIA convention)
export DGXSYSTEM=$(basename $(readlink -f ${BASH_SOURCE[1]}) | sed 's/^config_//' | sed 's/\.sh$//' )

export GPUS_PER_NODE=8                           # ranks the trainer spawns on each node
export HIP_VISIBLE_DEVICES=0,1,2,3,4,5,6,7
export CUDA_VISIBLE_DEVICES=0,1,2,3,4,5,6,7
export START_TS=0                                # full reference sweep: windows 0..298, full train and eval sets
export NUM_TRAIN_TS=299
export NUM_TRAIN_BATCHES=0
export NUM_EVAL_BATCHES=0
export EVAL_EVERY_N_WINDOWS=0
export EVAL_EVERY_DATA_PCT=0.001                 # evaluate every 0.1% of the training stream
export AUC_THRESHOLD=0.75                        # quality target (eval AUC)
export LR_WARMUP_STEPS=24000                     # fixed by the benchmark (not tunable)
export LR_WARMUP_START_LR=0.0
export MLPERF_LOGGING=1
export MLPERF_SUBMISSION_PLATFORM=MI350X         # logged as submission_platform
export CLEAR_CACHES=1                            # page-cache flush before every run (MLPerf cache_clear)
export FLYDSL_GPU_ARCH=gfx950                    # MI350X; without it FlyDSL can fall back to gfx942 and abort
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export HSTU_HAMMER_KERNEL=TRITON
export NCCL_DEBUG=WARN
export DLRM_DATA_PATH=/data/mlperf_dlrm_v4       # dataset path inside the container (run_with_docker*.sh mount DATADIR here)
